function save(){localStorage.setItem('dc-cart',JSON.stringify(state.cart));localStorage.setItem('dc-wish',JSON.stringify(state.wish));renderCounts()}
function renderCounts(){document.querySelectorAll('[data-cart-count]').forEach(e=>e.textContent=state.cart.reduce((a,x)=>a+x.qty,0));document.querySelectorAll('[data-wish-count]').forEach(e=>e.textContent=state.wish.length)}
function toast(t){state.toast=t;renderToast();setTimeout(()=>{state.toast='';renderToast()},2100)}function renderToast(){let old=document.querySelector('.toast');if(old)old.remove();if(state.toast){let d=document.createElement('div');d.className='toast';d.textContent=state.toast;document.body.append(d)}}
function header(){return `<header class="sitehead"><div class="wrap nav"><a class="brand" href="#home"><img class="logoimg" src="/images/logo.png" alt="Kalaai logo"/><span><span class="brandname">Kalaai</span><span class="brandtag">BRING HOME DIVINITY</span></span></a><nav class="navlinks" id="navlinks"><a href="#home" data-page="home">Home</a><a href="#shop" data-page="shop">Shop</a><a href="#shop" data-page="shop">Categories</a><a href="#custom" data-page="custom">Custom Orders</a><a href="#about" data-page="about">About Us</a><a href="#contact" data-page="contact">Contact</a></nav><div class="navtools"><button class="iconbtn" aria-label="Search" data-action="navigate" data-page="shop">⌕</button><button class="iconbtn" aria-label="Wishlist" data-action="navigate" data-page="wishlist">♡<span class="count" data-wish-count>${state.wish.length}</span></button><button class="iconbtn" aria-label="Cart" data-action="navigate" data-page="cart">♧<span class="count" data-cart-count>${state.cart.reduce((a,x)=>a+x.qty,0)}</span></button><button class="iconbtn hamb" aria-label="Open menu" data-action="toggle-menu">☰</button></div></div></header>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footgrid"><div><div class="brand"><img class="logoimg" src="/images/logo.png" alt="Kalaai logo"/><span><span class="brandname">Kalaai</span><span class="brandtag">BRING HOME DIVINITY</span></span></div><p style="max-width:260px;margin-top:18px">Art that inspires. Craft that lasts. Thoughtful handcrafted creations for meaningful moments.</p></div><div><h4>Explore</h4><a href="#home">Home</a><a href="#shop">Shop</a><a href="#about">Our Story</a><a href="#custom">Custom Orders</a></div><div><h4>Customer Care</h4><a href="#contact">Contact Us</a><a href="#faq">FAQs</a><a href="#shipping">Shipping Information</a><a href="#returns">Returns Policy</a><a href="/privacy-policy">Privacy Policy</a><a href="/terms-and-conditions">Terms &amp; Conditions</a><button class="footer-cookie-link" type="button" aria-label="Manage cookie preferences" data-action="cookie-settings">Cookie Preferences</button></div><div><h4>Get in touch</h4><p>Email: <a href="mailto:pareshp2006@gmail.com">pareshp2006@gmail.com</a></p><p>Phone: <a href="tel:8652237770">8652237770</a> / <a href="tel:9773237770">97732 37770</a></p><p>Address: Maharashtra, Mumbai, Ghatkopar, 400086</p><a class="social-link" href="https://www.instagram.com/kalaai.by.paddy?cplk=MWxqMmljNjI2aHBkMQ==" target="_blank" rel="noopener noreferrer" aria-label="Follow Kalaai on Instagram"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 2h10a5 5 0 015 5v10a5 5 0 01-5 5H7a5 5 0 01-5-5V7a5 5 0 015-5zm0 2a3 3 0 00-3 3v10a3 3 0 003 3h10a3 3 0 003-3V7a3 3 0 00-3-3H7zm5 3.5A5.5 5.5 0 1116.5 13 5.5 5.5 0 0112 7.5zm0 2A3.5 3.5 0 1015.5 13 3.5 3.5 0 0012 9.5zm5.75-3.25a1.25 1.25 0 110 2.5 1.25 1.25 0 010-2.5z"/></svg>Instagram</a></div></div><div class="copyright">© 2026 Kalaai. All Rights Reserved. <span style="float:right">Bring Home Divinity, Crafted With Care.</span></div></div></footer>`}
function privacyPolicy(){return `${pageHero('Privacy Policy','How Kalaai handles the information you share with us.')}<section class="wrap legal"><p><strong>Last updated:</strong> 16 November 2026</p><p>This draft describes the data handling visible in the current Kalaai website project. It is not a substitute for review by the business owner or legal adviser. Complete the clearly marked items before publishing.</p><h2>1. Information we collect</h2><ul><li>Paid orders: name, email address, phone number, delivery address, selected products, quantities, personalisation details and payment reference identifiers. Card details are handled by Razorpay and are not stored by Kalaai.</li><li>Contact and custom enquiries: name, email address, phone number (if supplied), subject, message, category, occasion, budget and design description.</li><li>Newsletter subscriptions: email address, stored in the Kalaai database. The site does not send newsletters or marketing emails.</li><li>Administrator access: username and an authentication session cookie. Passwords are checked against a server-side configured credential and are not stored in the customer database.</li><li>Store preferences: cart and wishlist entries are stored in this browser's local storage.</li><li>Reference images submitted with custom or contact enquiries are validated and saved by the server. The image link is available to authorised administrators.</li></ul><h2>2. Why we use information</h2><p>Information is used to respond to enquiries, review custom requests, process paid orders, coordinate fulfilment, maintain the app-only newsletter list, operate the website and protect the administrator area.</p><h2>3. Storage and processing</h2><p>Order, enquiry and newsletter subscription details are saved by the website backend in its configured MongoDB database. Payment is processed by Razorpay; Kalaai stores payment identifiers and verification status, not card details. The actual database provider, hosting region, access controls and backup arrangements depend on the deployment configuration and must be confirmed by Kalaai. Browser cart and wishlist data remain in local storage on the device used.</p><h2>4. Sharing and service providers</h2><p>The project integrates Razorpay Checkout in test mode for payment processing. If the owner configures Meta WhatsApp Cloud API, order number, customer contact and delivery details, items and total are sent to the configured admin WhatsApp number using an approved template. It does not integrate an email-marketing or shipping-carrier service; newsletter addresses are stored for the owner and no messages are sent. Google Fonts are requested from Google Fonts when pages load, which may disclose technical request information to that provider. The hosting provider and MongoDB provider will process data as necessary to operate the service; <strong>their names and locations must be completed by the owner</strong>.</p><h2>5. Cookies and tracking</h2><p>The admin sign-in uses an HttpOnly, SameSite=Strict session cookie (Secure over HTTPS in production). The storefront uses local storage for cart, wishlist and cookie preference settings. No optional analytics or marketing trackers are configured in this project. If optional tracking is added later, it must remain disabled until the required consent is obtained.</p><h2>6. Retention and deletion</h2><p>The current application does not implement an automatic retention schedule or a customer self-service deletion workflow. Order and enquiry records remain in the database until the business owner deletes them under an approved retention policy. To request access, correction or deletion, contact Kalaai using the contact details completed below.</p><h2>7. Your choices and rights</h2><p>Depending on applicable law, you may have rights to request access to, correction of or deletion of personal information, and to raise a privacy concern. You can clear cart and wishlist information through your browser storage settings. You can change cookie preferences using the footer link.</p><h2>8. Security</h2><p>The application uses server-side validation, access checks for administrator APIs, rate limits and security headers. No internet-connected system can be guaranteed completely secure. Do not send payment card details or passwords through the enquiry forms.</p><h2>9. Children</h2><p>This website is not designed to knowingly collect personal information from children. The owner should add an age-related policy if the business intends to serve children directly.</p><h2>10. Contact and owner details</h2><p><strong>Business/legal name:</strong> [OWNER TO COMPLETE]<br><strong>Privacy contact email:</strong> [OWNER TO COMPLETE]<br><strong>Postal/business address:</strong> [OWNER TO COMPLETE]<br><strong>Hosting provider and country:</strong> [OWNER TO COMPLETE]<br><strong>Database provider and country:</strong> [OWNER TO COMPLETE]</p><p>For a privacy request, use the confirmed contact email above. This policy must be reviewed and approved by the business owner before production use.</p></section>`}
function termsPage(){return `${pageHero('Terms & Conditions','Important information about using the Kalaai website.')}<section class="wrap legal"><p><strong>Last updated:</strong> 16 November 2026</p><p>This draft reflects the features and limitations visible in the current project. Business policies and legal details marked for owner approval must be completed before publication.</p><h2>1. Website use</h2><p>You may use this website to browse the catalogue, save items in your browser, submit enquiries, and use Razorpay test-mode checkout for lawful purposes. Do not misuse the website, interfere with its operation, attempt unauthorised access or submit false or harmful content.</p><h2>2. Catalogue and product information</h2><p>Product images, descriptions, availability and prices are illustrative catalogue information in the current project. Prices are marked as sample prices and must be confirmed by Kalaai. A product display uses sample catalogue prices. Test payments do not represent live charges or an accepted commercial sale.</p><h2>3. Enquiries and order requests</h2><p>Submitting an enquiry allows Kalaai to contact you. A paid checkout uses Razorpay in test mode, with the fixed shipping amount shown at checkout; payments cannot be collected live through this version. Test-mode orders are recorded only after the payment response is verified by the server.</p><h2>4. Accounts and administrator access</h2><p>There are no customer registration or customer account features in the current website. The administrator area is restricted to authorised personnel.</p><h2>5. Payments, cancellations, refunds and delivery</h2><p><strong>Owner approval required:</strong> live payment processing, order cancellation rules, refund/return eligibility, delivery regions, delivery estimates, damage/loss handling and custom-order cancellation terms require owner approval. The configured shipping fee is fixed and must be reviewed and clearly disclosed before use. Do not treat this draft as establishing any other policy.</p><h2>6. Personalised and custom work</h2><p>Custom requests are subject to discussion and confirmation with Kalaai. The owner should approve policies for design proofs, customer-supplied images, revisions, production timelines and final acceptance before taking paid orders.</p><h2>7. Intellectual property</h2><p>Website branding, text, design elements and catalogue content are intended to be used by Kalaai or their respective rights holders. You may not copy, reproduce or commercially exploit them without permission. Customers remain responsible for having rights to images, names, logos or other materials they submit.</p><h2>8. User responsibilities</h2><p>Provide accurate contact information, submit only content you are entitled to share, and do not attempt to disrupt or compromise the website. Do not submit sensitive payment information through forms.</p><h2>9. Availability and liability</h2><p>The website is provided subject to availability. To the extent permitted by applicable law, Kalaai is not responsible for indirect loss arising from temporary unavailability, inaccurate draft catalogue information or unauthorised use outside its reasonable control. Nothing here excludes liability that cannot legally be excluded.</p><h2>10. Governing law and disputes</h2><p><strong>Owner/legal adviser to complete:</strong> applicable governing law, court jurisdiction, dispute-resolution and escalation process, and the legal entity that contracts with customers. Do not publish a governing-law clause until approved.</p><h2>11. Changes and contact</h2><p>These terms may be updated as the business and website evolve. Contact details must be completed before launch: <strong>Business/legal name:</strong> [OWNER TO COMPLETE]; <strong>email:</strong> [OWNER TO COMPLETE]; <strong>postal address:</strong> [OWNER TO COMPLETE].</p><p>This draft requires business-owner and legal review before production use.</p></section>`}
function faqPage(){return `${pageHero('Frequently Asked Questions','Answers to common questions about Kalaai creations and custom orders.')}<section class="wrap legal"><h2>Can I personalise a product?</h2><p>Yes. Open a product to see the available name, photo, message or design fields.</p><h2>How do I place a custom order?</h2><p>Use the Custom Orders page to describe your idea and share your preferred category, occasion and budget.</p><h2>Are reference images uploaded?</h2><p>Yes. Custom and contact enquiries accept JPG, PNG, GIF or WebP images up to 5 MB. The uploaded file is saved and linked in the admin enquiry panel.</p><h2>How can I track an order?</h2><p>For a confirmed order, contact Kalaai with your order reference. Live carrier tracking is not integrated yet.</p><h2>How can I contact Kalaai?</h2><p>Email pareshp2006@gmail.com or call 8652237770 / 97732 37770.</p></section>`}
function shippingPage(){return `${pageHero('Shipping Information','Delivery, preparation and checkout information.')}<section class="wrap legal"><h2>Preparation</h2><p>Handcrafted pieces may require additional preparation time. Timing is confirmed with Kalaai for each order.</p><h2>Shipping fee</h2><p>The website can use one fixed INR shipping fee configured by the store owner. The exact fee is shown in the cart before payment.</p><h2>Delivery tracking</h2><p>Shipping-carrier integration is not enabled in this version. Use the order reference and contact details for delivery updates.</p></section>`}
function returnsPage(){return `${pageHero('Returns & Cancellations','Policy status and how to request assistance.')}<section class="wrap legal"><h2>Custom and personalised items</h2><p>Custom pieces may be subject to special cancellation and return terms. Approval should be confirmed before production begins.</p><h2>Damaged or incorrect items</h2><p>Contact Kalaai promptly with the order reference and clear photographs so the team can assess the issue.</p><h2>Business policy</h2><p>Final eligibility, refund timing and cancellation deadlines must be confirmed by the owner for each order.</p></section>`}
function sectionHead(k,t,d){return `<div class="sectionhead"><div class="eyebrow">${k}</div><h2 class="serif">${t}</h2><p>${d}</p></div>`}
function card(p){return `<article class="product"><div class="product-img"><img loading="lazy" src="${escapeHtml(p.image)}" alt="${escapeHtml(p.name)}"><button class="wish ${state.wish.includes(p.id)?'on':''}" aria-label="Add to wishlist" data-action="toggle-wish" data-id="${p.id}">${state.wish.includes(p.id)?'♥':'♡'}</button><button class="btn quick" data-action="quick-view" data-id="${p.id}">Quick View</button></div><div class="product-info"><div class="product-cat">${escapeHtml(p.category)}</div><h3>${escapeHtml(p.name)}</h3><div class="price">${money(p.price)} <span class="notice">· sample price</span></div><div class="product-actions"><button class="btn outline" data-action="open-product" data-id="${p.id}">View Details</button><button class="btn" data-action="add-cart" data-id="${p.id}">Add to Cart</button></div></div></article>`}
function home(){return `<main><div class="wrap hero"><div class="hero-copy"><div class="eyebrow">KALAAI &nbsp;|&nbsp; HANDCRAFTED WITH LOVE</div><h1 class="serif">Bring Home <span>Divinity.</span></h1><h3 class="serif" style="font-size:29px;color:var(--beige);font-weight:400">Unique creations. Personalised memories. Timeless craftsmanship.</h3><p>Discover handcrafted resin art, spiritual decor and personalised creations designed to make every moment special.</p><div class="actions"><a class="btn" href="#shop">Explore Collection</a><a class="btn outline" href="#custom">Create Your Custom Order</a></div></div><div class="hero-photo"><img src="${products[0].image}" alt="Handcrafted personalised resin letter artwork"><div class="hero-note"><strong>Made with meaning.</strong><span class="muted">One-of-a-kind details, crafted with care.</span></div></div></div><div class="benefits"><div class="wrap benefit-grid"><div class="benefit"><span class="sym">✧</span><span><b>Premium Quality</b>Care in every detail</span></div><div class="benefit"><span class="sym">◇</span><span><b>Custom Creations</b>Made personal to you</span></div><div class="benefit"><span class="sym">⌖</span><span><b>Fixed Shipping</b>Fixed rate shown at checkout</span></div><div class="benefit"><span class="sym">♡</span><span><b>Made With Love</b>Thoughtful handcrafted art</span></div></div></div><section class="wrap">${sectionHead('A WORLD OF HANDCRAFTED ART','Explore Our Collections','Discover something special for every occasion.')}<div class="category-grid">${categories.slice(0,4).map((c,i)=>`<a href="#shop" class="cat-card" data-action="shop-category" data-category="${escapeHtml(c)}"><img loading="lazy" src="${products[[3,0,9,12][i]].image}" alt="${c}"><div class="cat-info"><h3>${c}</h3><p>Thoughtfully crafted, made to be treasured.</p><span class="textlink">Explore collection →</span></div></a>`).join('')}</div></section><section style="background:var(--espresso)"><div class="wrap">${sectionHead('FAVOURITES FROM THE STUDIO','Curated With Care','Explore our most loved handcrafted creations.')}<div class="productgrid">${products.slice(0,8).map(card).join('')}</div><div style="text-align:center;margin-top:32px"><a class="btn outline" href="#shop">View All Creations</a></div></div></section><section class="wrap"><div class="promo"><div><div class="eyebrow">PERSONALISED JUST FOR YOU</div><h2 class="serif">Made Just for You.</h2><p class="muted">Your memories, your imagination, our craftsmanship. Turn your ideas into beautifully personalised creations.</p><p class="muted">Custom nameplates · Personalised keychains · Photo frames · Anniversary gifts · Name art</p><a class="btn" href="#custom">Request a Custom Creation</a></div><img loading="lazy" src="${products[21].image}" alt="Personalised family keepsake plaque"></div></section><section class="wrap editorial"><img loading="lazy" src="${products[23].image}" alt="Spiritual handcrafted resin plaque"><div><div class="eyebrow">CRAFTED WITH PURPOSE</div><h2 class="serif">Art that Inspires.<br><span class="gold">Craft that Lasts.</span></h2><p class="muted">From spiritual resin art to personal photo keepsakes, each piece brings together thoughtful detail and a personal story.</p><div class="editorial-list"><div class="editorial-item"><b>01</b><div>Unique Designs</div><small class="muted">Distinctive ideas and expressive forms.</small></div><div class="editorial-item"><b>02</b><div>Premium Quality</div><small class="muted">A careful eye for finish and detail.</small></div><div class="editorial-item"><b>03</b><div>Made With Care</div><small class="muted">Crafted with patience and attention.</small></div><div class="editorial-item"><b>04</b><div>Personalised Creations</div><small class="muted">Created around your memories.</small></div></div></div></section><section style="background:var(--espresso)"><div class="wrap">${sectionHead('FROM IDEA TO KEEPSAKE','Your Creation, Step by Step','A simple collaborative journey from imagination to a finished piece.')}<div class="steps">${[['01','Share Your Idea'],['02','Discuss Your Design'],['03','We Create Your Product'],['04','Your Creation Is Ready']].map(x=>`<div class="step"><strong>${x[0]}</strong><h3 class="serif">${x[1]}</h3><p class="muted">Thoughtful details at every stage.</p></div>`).join('')}</div></div></section><section class="newsletter"><div class="wrap"><div class="eyebrow">A NOTE FROM OUR STUDIO</div><h2 class="serif">Stay Connected With Kalaai</h2><p class="muted">Join Kalaai?s app-only subscriber list for future updates. Your address is saved here; no emails are sent yet.</p><form class="newsform" data-form="newsletter"><input class="field" id="subscribeEmail" name="email" type="email" autocomplete="email" placeholder="Your email address" required><button class="btn">Subscribe</button></form><p id="subscribeMsg" class="notice"></p></div></section></main>`}
function pageHero(title,desc){return `<div class="pagehero"><div class="wrap"><div class="eyebrow">KALAAI COLLECTION</div><h1 class="serif" style="font-size:clamp(42px,6vw,68px);margin:10px 0">${title}</h1><p class="muted">${desc}</p></div></div>`}
function filterBox(){const opts=['Spiritual Art','Resin Name Letters','Personalised Gifts','Photo Memories','Keychains','Nameplates','Home Decor','Clocks','Wedding Gifts','Anniversary Gifts','Birthday Gifts','Custom Creations'];return `<aside class="filters ${state.filterOpen?'mobileopen':''}" id="filters"><div style="display:flex;justify-content:space-between"><h3 class="serif">Refine Your Search</h3><button class="iconbtn" aria-label="Close filters" data-action="close-filters">×</button></div><div class="filtergroup"><h4>Category</h4>${opts.map(c=>`<label class="check"><input type="checkbox" ${state.cat.includes(c)?'checked':''} data-category-filter="${escapeHtml(c)}">${c}</label>`).join('')}</div><div class="filtergroup"><h4>Price Range</h4><div class="muted" style="font-size:11px;display:flex;justify-content:space-between"><span>₹0</span><span id="rangeValue">${money(window.maxPrice||10000)}</span></div><input class="range" type="range" min="0" max="10000" step="100" value="${window.maxPrice||10000}" data-input="price-range"><div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:12px">${[['Under ₹500',0,500],['₹500–1,000',500,1000],['₹1,000–2,500',1000,2500],['₹2,500–5,000',2500,5000],['Above ₹5,000',5000,10000]].map(a=>`<button class="btn outline" style="padding:7px;font-size:8px" data-action="set-price" data-min="${a[1]}" data-max="${a[2]}">${a[0]}</button>`).join('')}</div></div><div class="filtergroup"><h4>Occasion</h4>${['Birthday','Wedding','Anniversary','Housewarming','Festival','Religious Occasion','Baby Celebration','Corporate Gifting','Everyday Decor'].map(c=>`<label class="check"><input type="checkbox" class="occasion" value="${c}" data-change="apply-shop">${c}</label>`).join('')}</div><div class="filtergroup"><h4>Product Type</h4>${['Wall Decor','Table Decor','Personalised Keychain','Photo Frame','Name Art','Decorative Plaque','Resin Art','Custom Gift'].map(c=>`<label class="check"><input type="checkbox" class="ptype" value="${c}" data-change="apply-shop">${c}</label>`).join('')}</div><div class="filtergroup"><h4>Personalisation</h4>${['Personalised Available','Name','Photo','Text','Design'].map(c=>`<label class="check"><input type="checkbox" class="personal" value="${c}" data-change="apply-shop">${c==='Name'?'Name Customisation':c==='Photo'?'Photo Customisation':c==='Text'?'Text Customisation':c==='Design'?'Custom Design Available':c}</label>`).join('')}<label class="check"><input type="checkbox" class="personal" value="ready">Ready-Made Products</label></div><div class="filtergroup"><h4>Availability <span class="notice">(illustrative)</span></h4>${['In Stock','Made to Order','Custom Order Only'].map(c=>`<label class="check"><input type="checkbox" class="avail" value="${c}" data-change="apply-shop">${c}</label>`).join('')}</div><button class="btn" style="width:100%;margin-top:15px" data-action="apply-shop">Apply Filters</button><button class="btn outline" style="width:100%;margin-top:8px" data-action="clear-filters">Clear All</button></aside>`}
function shop(){return `${pageHero('Discover Our Collection','Explore handcrafted art and personalised creations designed to celebrate your special moments.')}<section class="wrap"><div class="shoplayout">${filterBox()}<div><div class="shopbar"><button class="btn outline filter-toggle" data-action="toggle-filters">☷ Filters</button><div class="search"><input id="searchInput" class="field" placeholder="Search products, categories, occasions..." value="${state.query.replaceAll('"','&quot;')}" data-input="search"><button class="btn outline" data-action="clear-search">×</button></div><div class="toolbar-right"><span class="notice" id="resultCount"></span><select id="sortSelect" data-change="sort"><option>Featured</option><option>Newest First</option><option>Price: Low to High</option><option>Price: High to Low</option><option>Name: A to Z</option><option>Most Popular</option></select></div></div><div class="productgrid" id="shopResults"></div></div></div></section>`}
function applyShop(){let list=[...products];if(state.cat.length)list=list.filter(p=>state.cat.includes(p.category)||state.cat.some(c=>c==='Nameplates'&&p.productType==='Nameplate'||c==='Wedding Gifts'&&p.occasions.includes('Wedding')||c==='Anniversary Gifts'&&p.occasions.includes('Anniversary')||c==='Birthday Gifts'&&p.occasions.includes('Birthday')||c==='Custom Creations'&&p.personalised));if(window.minPrice!=null)list=list.filter(p=>p.price>=window.minPrice);if(window.maxPrice!=null)list=list.filter(p=>p.price<=window.maxPrice);const occ=[...document.querySelectorAll('.occasion:checked')].map(x=>x.value);const typ=[...document.querySelectorAll('.ptype:checked')].map(x=>x.value);const pers=[...document.querySelectorAll('.personal:checked')].map(x=>x.value);const av=[...document.querySelectorAll('.avail:checked')].map(x=>x.value);if(occ.length)list=list.filter(p=>occ.some(x=>p.occasions.includes(x)));if(typ.length)list=list.filter(p=>typ.includes(p.productType));if(pers.length)list=list.filter(p=>pers.some(x=>x==='ready'?!p.personalised:x==='Personalised Available'?p.personalised:p.personalisationTypes.includes(x)));if(av.length)list=list.filter(p=>av.includes(p.availability));let q=state.query.toLowerCase().trim();if(q)list=list.filter(p=>[p.name,p.category,p.productType,...p.occasions,...p.tags].join(' ').toLowerCase().includes(q));switch(state.sort){case'Newest First':list.sort((a,b)=>b.dateAdded.localeCompare(a.dateAdded));break;case'Price: Low to High':list.sort((a,b)=>a.price-b.price);break;case'Price: High to Low':list.sort((a,b)=>b.price-a.price);break;case'Name: A to Z':list.sort((a,b)=>a.name.localeCompare(b.name));break;case'Most Popular':list.sort((a,b)=>b.popularity-a.popularity);break;case'Featured':list.sort((a,b)=>Number(b.featured)-Number(a.featured));}
const dest=document.getElementById('shopResults');if(!dest)return;dest.innerHTML=list.length?list.map(card).join(''):`<div class="empty"><h3 class="serif">No creations found matching your selection.</h3><p>Try adjusting your filters or search terms.</p><button class="btn" data-action="clear-filters">Clear Filters</button></div>`;const count=document.getElementById('resultCount');if(count)count.textContent=`${list.length} creations`}
function toggleCat(c){state.cat=state.cat.includes(c)?state.cat.filter(x=>x!==c):[...state.cat,c];applyShop()}
function clearFilters(){state.cat=[];state.query='';window.minPrice=null;window.maxPrice=10000;state.sort='Featured';render()}
function shopCategory(c){state.cat=[c];state.page='shop';state.quick=null;history.replaceState(null,'',`#shop?cat=${encodeURIComponent(c)}`);render();window.scrollTo(0,0)}
function openProduct(id){state.selected=id;state.qty=1;state.tab='Description';navigate('product')}
function detail(){let p=products.find(x=>x.id===state.selected)||products[0];return `<div class="wrap"><div class="crumb"><a href="#home">Home</a> / <a href="#shop">Shop</a> / ${escapeHtml(p.category)} / ${escapeHtml(p.name)}</div><div class="detail"><div><div class="gallerymain"><img src="${escapeHtml(p.image)}" alt="${escapeHtml(p.name)}" id="detailImage" data-action="lightbox" data-src="${escapeHtml(p.image)}"></div><div class="thumbs"><img src="${escapeHtml(p.image)}" alt="${escapeHtml(p.name)} thumbnail" data-action="detail-image" data-src="${escapeHtml(p.image)}"></div></div><div><div class="eyebrow">${escapeHtml(p.category)}</div><h1 class="serif">${escapeHtml(p.name)}</h1><div class="price" style="font-size:22px">${money(p.price)} <span class="notice">· sample price</span></div><p class="desc" style="margin-top:20px">${escapeHtml(p.description)}</p><p class="notice">Availability: ${escapeHtml(p.availability)} (illustrative catalogue status)</p>${p.personalised?`<div class="panel" style="margin:20px 0"><h3 class="serif">Make it personal</h3>${p.personalisationTypes.includes('Name')?'<label class="formlabel">Your Name<input id="pName" class="field" placeholder="Enter name"></label>':''}${p.personalisationTypes.includes('Photo')?'<label class="formlabel">Reference Photo<input id="pPhoto" type="file" accept="image/*" class="field" data-change="preview-file"><span id="photoPreview"></span></label>':''}${p.personalisationTypes.includes('Text')?'<label class="formlabel">Special Message<textarea id="pText" class="field" rows="2" placeholder="Add a message"></textarea></label>':''}${p.personalisationTypes.includes('Design')?'<label class="formlabel">Design Preference<textarea id="pDesign" class="field" rows="2" placeholder="Tell us about your preferred design"></textarea></label>':''}</div>`:''}<div class="qty"><span>Quantity</span><button aria-label="Decrease quantity" data-action="detail-qty" data-change="-1">−</button><b id="qnum">1</b><button aria-label="Increase quantity" data-action="detail-qty" data-change="1">+</button></div><div class="actions"><button class="btn" data-action="add-cart-state" data-id="${p.id}">Add to Cart</button><button class="btn outline" data-action="toggle-wish" data-id="${p.id}">♡ Add to Wishlist</button></div><div class="tabs">${['Description','Product Details','Personalisation','Care Instructions'].map(t=>`<button class="${state.tab===t?'active':''}" data-action="set-tab" data-tab="${escapeHtml(t)}">${t}</button>`).join('')}</div><p class="muted" style="margin-top:18px">${state.tab==='Description'?p.description:state.tab==='Product Details'?`Product type: ${escapeHtml(p.productType)}. Category: ${escapeHtml(p.category)}.`:state.tab==='Personalisation'?`Available options: ${escapeHtml(p.personalisationTypes.join(', ')||'No personalisation fields for this item')}.`:'Keep away from harsh chemicals. Wipe gently with a soft, dry cloth.'}</p></div></div><h2 class="serif">You May Also Like</h2><div class="productgrid">${products.filter(x=>x.category===p.category&&x.id!==p.id).slice(0,4).map(card).join('')}</div></div>`}
function personalDetails(){return {name:document.getElementById('pName')?.value||'',text:document.getElementById('pText')?.value||'',design:document.getElementById('pDesign')?.value||'',photo:document.getElementById('pPhoto')?.files?.[0]?.name||''}}
function previewFile(el){const f=el.files[0];if(f){const url=URL.createObjectURL(f);document.getElementById('photoPreview').innerHTML=`<img src="${url}" alt="Selected reference image preview" style="width:100px;margin-top:8px">`}}
function addCart(id,qty=1,custom={}){let p=products.find(x=>x.id===id);let key=JSON.stringify(custom||{});let old=state.cart.find(x=>x.id===id&&JSON.stringify(x.custom||{})===key);if(old)old.qty+=qty;else state.cart.push({id,qty,custom:custom||{}});save();toast('Added to your shopping bag')}
function toggleWish(id){state.wish=state.wish.includes(id)?state.wish.filter(x=>x!==id):[...state.wish,id];save();toast(state.wish.includes(id)?'Added to wishlist':'Removed from wishlist');if(state.page==='wishlist')render()}
function quickView(id){state.quick=id;const p=products.find(x=>x.id===id);document.body.insertAdjacentHTML('beforeend',`<div class="modalback" data-action="modal-backdrop"><div class="modal"><button class="modalclose" aria-label="Close dialog" data-action="close-modal">×</button><div class="quicklayout"><img src="${escapeHtml(p.image)}" alt="${escapeHtml(p.name)}"><div><div class="product-cat">${escapeHtml(p.category)}</div><h2 class="serif">${escapeHtml(p.name)}</h2><div class="price">${money(p.price)}</div><p class="muted">${escapeHtml(p.description)}</p><p class="notice">${p.personalised?'Personalisation available':'Ready-made design'}</p><div class="qty"><button aria-label="Decrease quantity" data-action="quick-view-qty" data-change="-1">−</button><b id="qvnum">1</b><button aria-label="Increase quantity" data-action="quick-view-qty" data-change="1">+</button></div><button class="btn" data-action="quick-view-add" data-id="${p.id}">Add to Cart</button><p style="margin-top:16px"><a class="textlink" href="#product/${p.id}" data-action="modal-open-product" data-id="${p.id}">View Full Details →</a></p></div></div></div></div>`)}
function lightbox(src){document.body.insertAdjacentHTML('beforeend',`<div class="modalback" data-action="modal-backdrop"><img src="${src}" alt="Enlarged product image" style="max-height:85vh;max-width:90vw;object-fit:contain"></div>`)}
function cart(){let subtotal=state.cart.reduce((a,x)=>a+(products.find(p=>p.id===x.id)?.price||0)*x.qty,0);const fee=checkoutConfig.whatsappShippingFee||0;return `${pageHero('Your Shopping Bag','Review the creations you have chosen.')}<section class="wrap">${state.cart.length?`<div class="panel">${state.cart.map(x=>{let p=products.find(y=>y.id===x.id);return `<div class="cartrow"><img src="${escapeHtml(p.image)}" alt="${escapeHtml(p.name)}"><div><div class="product-cat">${escapeHtml(p.category)}</div><h3 class="serif">${escapeHtml(p.name)}</h3><div class="price">${money(p.price)}</div><div class="notice">${escapeHtml(Object.values(x.custom||{}).filter(Boolean).join(' · '))}</div><div class="qty"><button data-action="cart-qty" data-id="${p.id}" data-change="-1">−</button><b>${x.qty}</b><button data-action="cart-qty" data-id="${p.id}" data-change="1">+</button></div></div><div><b class="price">${money(p.price*x.qty)}</b><button class="iconbtn" data-action="remove-cart" data-id="${p.id}">×</button></div></div>`}).join('')}</div><div class="carttotal"><div class="cartline"><span>Subtotal</span><b>${money(subtotal)}</b></div><div class="cartline"><span>Fixed shipping</span><span>${fee?money(fee):'Free / confirmed on WhatsApp'}</span></div><div class="cartline total"><span>Total</span><b>${money(subtotal+fee)}</b></div><p class="notice">Pay later: Kalaai will confirm your order and payment details with you on WhatsApp.</p><div class="actions"><a class="btn outline" href="#shop">Continue Shopping</a><button class="btn" data-action="checkout">Proceed to Checkout</button></div></div>`:`<div class="empty"><h2 class="serif">Your bag is waiting for something meaningful.</h2><p>Explore the collection and find a creation to treasure.</p><a class="btn" href="#shop">Explore Collection</a></div>`}</section>`}
function cartQty(id,n){let x=state.cart.find(x=>x.id===id);if(x){x.qty=Math.max(1,x.qty+n);save();render()}}function removeCart(id){state.cart=state.cart.filter(x=>x.id!==id);save();render()}
function orderImage(o){
  const W=900,pad=48,rupee=n=>'Rs. '+Number(n).toLocaleString('en-IN');
  const measure=document.createElement('canvas').getContext('2d');
  const wrap=(ctx,text,maxW)=>{const out=[];String(text).split(/\n/).forEach(par=>{let line='';par.split(/\s+/).forEach(w=>{const t=line?line+' '+w:w;if(ctx.measureText(t).width>maxW&&line){out.push(line);line=w}else line=t});out.push(line)});return out};
  measure.font='24px sans-serif';
  const rows=o.items.map(i=>{const extra=Object.values(i.custom||{}).filter(Boolean).join(' | ');return{title:`${i.name}  x${i.quantity}`,amount:rupee(i.price*i.quantity),extra:extra?wrap(measure,extra,W-pad*2-200):[]}});
  const addr=wrap(measure,o.address,W-pad*2);
  let H=pad+130+60+rows.reduce((a,r)=>a+44+r.extra.length*30,0)+30+(o.shippingFee?44:0)+70+60+40+addr.length*34+80;
  const c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d');
  x.fillStyle='#fbf7f1';x.fillRect(0,0,W,H);x.fillStyle='#3b2a1d';x.fillRect(0,0,W,120);
  x.fillStyle='#e8c98f';x.font='bold 44px serif';x.fillText('Kalaai',pad,62);
  x.fillStyle='#f3e8d6';x.font='22px sans-serif';x.fillText('ORDER SUMMARY  |  '+o.orderNumber,pad,98);
  let y=120+50;x.fillStyle='#8b5e3c';x.font='bold 20px sans-serif';x.fillText('ITEMS',pad,y);y+=14;
  rows.forEach(r=>{y+=34;x.fillStyle='#2a1d13';x.font='bold 24px sans-serif';x.fillText(r.title,pad,y);x.textAlign='right';x.fillText(r.amount,W-pad,y);x.textAlign='left';x.font='22px sans-serif';x.fillStyle='#6b5543';r.extra.forEach(t=>{y+=30;x.fillText(t,pad+16,y)});y+=10});
  y+=14;x.strokeStyle='#d9c7ad';x.beginPath();x.moveTo(pad,y);x.lineTo(W-pad,y);x.stroke();
  if(o.shippingFee){y+=38;x.fillStyle='#6b5543';x.font='24px sans-serif';x.fillText('Shipping',pad,y);x.textAlign='right';x.fillText(rupee(o.shippingFee),W-pad,y);x.textAlign='left'}
  y+=46;x.fillStyle='#2a1d13';x.font='bold 30px sans-serif';x.fillText('TOTAL',pad,y);x.textAlign='right';x.fillText(rupee(o.total),W-pad,y);x.textAlign='left';
  y+=56;x.fillStyle='#8b5e3c';x.font='bold 20px sans-serif';x.fillText('PHONE',pad,y);y+=34;x.fillStyle='#2a1d13';x.font='26px sans-serif';x.fillText(o.phone,pad,y);
  y+=50;x.fillStyle='#8b5e3c';x.font='bold 20px sans-serif';x.fillText('DELIVERY ADDRESS',pad,y);x.fillStyle='#2a1d13';x.font='24px sans-serif';addr.forEach(t=>{y+=34;x.fillText(t,pad,y)});
  y+=50;x.fillStyle='#9a8670';x.font='italic 18px sans-serif';x.fillText('Generated by Kalaai checkout. Verified against the order saved on our server.',pad,y);
  return new Promise(resolve=>c.toBlob(resolve,'image/png'));
}
function checkoutDemo(){
  if(!state.cart.length){toast('Your bag is empty');return}
  document.querySelector('[data-modal="checkout"]')?.remove();
  document.body.insertAdjacentHTML('beforeend',`<div class="modalback" data-modal="checkout" data-action="modal-backdrop"><div class="modal"><button class="modalclose" aria-label="Close dialog" data-action="close-modal">×</button><div class="eyebrow">PLACE YOUR ORDER</div><h2 class="serif">Delivery Details</h2><p class="muted">Share your phone number and delivery address. We will take you to Kalaai on WhatsApp with your order summary so the team can confirm it with you.</p><form class="formgrid" id="checkoutForm"><div class="hp-field" aria-hidden="true"><label>Leave this field empty<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="wide"><span class="formlabel">Phone Number *</span><input class="field" name="phone" type="tel" autocomplete="tel" inputmode="tel" placeholder="e.g. 98765 43210" pattern="[+()\\d .\\-]{7,20}" required></label><label class="wide"><span class="formlabel">Delivery Address *</span><textarea class="field" name="address" rows="4" autocomplete="street-address" placeholder="House / flat no., street, area, city, state, PIN code" minlength="10" required></textarea></label><div class="wide"><p class="notice" id="orderMsg"></p><button class="btn" type="submit">Submit &amp; Continue on WhatsApp</button></div></form></div></div>`);
  document.getElementById('checkoutForm').addEventListener('submit',submitOrder);
}
async function submitOrder(e){
  e.preventDefault();
  const form=e.target,fields=new FormData(form),msg=document.getElementById('orderMsg'),button=form.querySelector('button[type=submit]');
  button.disabled=true;msg.textContent='Saving your order...';
  try{
    const response=await fetch('/api/checkout/whatsapp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({customer:{phone:fields.get('phone'),address:fields.get('address')},items:state.cart.map(item=>({id:item.id,qty:item.qty,custom:item.custom})),website:fields.get('website')||''})});
    const order=await response.json();
    if(!response.ok)throw Error(order.message||'Unable to place the order.');
    const blob=await orderImage(order);
    const file=new File([blob],`Kalaai-${order.orderNumber}.png`,{type:'image/png'});
    const url=URL.createObjectURL(blob);
    const text=`Hello Kalaai, I have placed order ${order.orderNumber}. Total: Rs. ${Number(order.total).toLocaleString('en-IN')}. Please find my order summary image attached.`;
    const waUrl=`https://wa.me/${order.whatsappNumber}?text=${encodeURIComponent(text)}`;
    state.cart=[];save();
    const box=form.closest('.modal');
    box.innerHTML=`<div class="eyebrow">ORDER ${escapeHtml(order.orderNumber)} SAVED</div><h2 class="serif">Almost done</h2><p class="muted">Your order summary image is below (it is also downloading). In WhatsApp, attach this image to the chat with Kalaai and press send. Opening WhatsApp now...</p><img src="${url}" alt="Order summary" style="max-width:100%;border:1px solid var(--line,#d9c7ad);margin:12px 0"><div class="actions"><a class="btn" href="${waUrl}" id="waLink">Open WhatsApp</a><a class="btn outline" href="${url}" download="${escapeHtml(file.name)}">Download Image</a></div>`;
    const a=document.createElement('a');a.href=url;a.download=file.name;document.body.append(a);a.click();a.remove();
    setTimeout(()=>{window.location.href=waUrl},2500);
  }catch(error){msg.textContent=error.message;button.disabled=false}
}
function wishlist(){let list=products.filter(p=>state.wish.includes(p.id));return `${pageHero('Your Wishlist','Keep the creations you love close at hand.')}<section class="wrap">${list.length?`<div class="productgrid">${list.map(p=>`<article class="product"><div class="product-img"><img src="${escapeHtml(p.image)}" alt="${escapeHtml(p.name)}"><button class="wish on" aria-label="Remove from wishlist" data-action="toggle-wish" data-id="${p.id}">♥</button></div><div class="product-info"><div class="product-cat">${escapeHtml(p.category)}</div><h3>${escapeHtml(p.name)}</h3><div class="price">${money(p.price)}</div><div class="product-actions"><button class="btn outline" data-action="open-product" data-id="${p.id}">Details</button><button class="btn" data-action="wishlist-move-cart" data-id="${p.id}">Move to Cart</button></div></div></article>`).join('')}</div>`:`<div class="empty"><h2 class="serif">Your wishlist is waiting for something beautiful.</h2><a class="btn" href="#shop">Explore Collection</a></div>`}</section>`}
function custom(){return `${pageHero('Your Imagination. Our Craftsmanship.','Have a unique idea in mind? Let us transform your vision into a beautiful handcrafted creation.')}<section class="wrap"><div class="editorial" style="margin-bottom:50px"><div><h2 class="serif">A Creation That Is Truly Yours.</h2><p class="muted">Personalised nameplates, custom resin art, photo frames, spiritual art, wedding memories, anniversary gifts, keychains and decorative pieces.</p><p class="muted">Share your idea and preferences. Your enquiry is submitted to Kalaai so the team can respond to your request.</p></div><img src="${products[2].image}" alt="Custom keepsake plaque"></div><div class="panel"><h2 class="serif">Tell Us What You Have in Mind</h2><form class="formgrid" data-form="custom-enquiry"><div class="hp-field" aria-hidden="true"><label>Leave this field empty<input name="website" tabindex="-1" autocomplete="off"></label></div><label><span class="formlabel">Full Name *</span><input class="field" name="name" required placeholder="Your name"></label><label><span class="formlabel">Email Address *</span><input class="field" name="email" required type="email" placeholder="you@example.com"></label><label><span class="formlabel">Phone Number</span><input class="field" name="phone" type="tel" placeholder="Your phone number"></label><label><span class="formlabel">Product Category *</span><select class="field" name="category" required><option value="">Select category</option>${categories.map(x=>`<option>${x}</option>`).join('')}</select></label><label><span class="formlabel">Occasion</span><select class="field" name="occasion"><option>Choose occasion</option>${['Birthday','Wedding','Anniversary','Housewarming','Festival','Religious Occasion','Baby Celebration','Corporate Gifting'].map(x=>`<option>${x}</option>`).join('')}</select></label><label><span class="formlabel">Preferred Budget</span><select class="field" name="budget"><option>Choose budget</option><option>Under ₹500</option><option>₹500–₹1,000</option><option>₹1,000–₹2,500</option><option>₹2,500–₹5,000</option><option>Above ₹5,000</option></select></label><label class="wide"><span class="formlabel">Design Description *</span><textarea class="field" name="designDescription" rows="5" required placeholder="Describe your idea, colours, names, dimensions or other details..."></textarea></label><label class="wide"><span class="formlabel">Upload Reference Image</span><input class="field" name="referenceImage" type="file" accept="image/jpeg,image/png,image/webp,image/gif" data-change="preview-enquiry"><div id="enquiryPreview"></div></label><div class="wide"><button class="btn">Submit Enquiry</button><p id="enquiryMsg" class="notice"></p></div></form></div></section>`}
function previewEnquiry(el){let f=el.files[0];if(f){let u=URL.createObjectURL(f),box=document.getElementById('enquiryPreview');box.replaceChildren();let wrap=document.createElement('div'),img=document.createElement('img'),label=document.createElement('span'),remove=document.createElement('button');wrap.style.cssText='display:flex;align-items:center;gap:12px;margin-top:12px';img.src=u;img.alt='Selected reference image preview';img.style.cssText='width:90px;height:90px;object-fit:cover';label.className='muted';label.textContent=f.name;remove.type='button';remove.className='btn outline';remove.textContent='Remove';remove.onclick=()=>{el.value='';box.replaceChildren()};wrap.append(img,label,remove);box.append(wrap)}}
async function submitEnquiry(e){e.preventDefault();const form=e.target,formData=new FormData(form);formData.set('type','custom');const msg=document.getElementById('enquiryMsg'),button=form.querySelector('button');button.disabled=true;msg.textContent='Uploading enquiry...';try{const r=await fetch('/api/enquiries',{method:'POST',body:formData});const d=await r.json();if(!r.ok)throw Error(d.message||'Unable to send');msg.textContent=d.message;form.reset();document.getElementById('enquiryPreview').innerHTML=''}catch(err){msg.textContent=err.message}finally{button.disabled=false}}
function about(){return `${pageHero('Crafting Memories. Creating Meaning.','At Kalaai, we believe that every creation should carry a story.')}<section class="wrap editorial"><img src="${products[24].image}" alt="Decorative handcrafted resin piece"><div><div class="eyebrow">OUR STORY</div><h2 class="serif">Small Details.<br><span class="gold">Meaningful Memories.</span></h2><p class="muted">Through handcrafted resin art, spiritual decor and personalised designs, Kalaai brings ideas and memories into thoughtfully made keepsakes.</p><h3 class="serif gold">Our Craftsmanship</h3><p class="muted">We celebrate expressive designs, considered details and personal touches. The catalogue brings together devotional plaques, custom lettering, photo memories and resin keepsakes.</p><h3 class="serif gold">Our Creative Philosophy</h3><p class="muted">A meaningful object can carry a name, a memory, a blessing or a moment worth keeping.</p><h3 class="serif gold">Our Commitment to Quality</h3><p class="muted">Every piece is presented with care, and each custom idea begins with understanding what matters to you.</p></div></section>`}
function contact(){return `${pageHero('We Would Love to Hear From You','Questions, ideas or a custom creation in mind? Send us a note.')}<section class="wrap"><div class="editorial"><div><h2 class="serif">Let’s Create Something Meaningful.</h2><p class="muted">Use the form to share a message or a question, or reach out directly through the contact details below.</p><div class="panel"><h3 class="serif gold">Contact Details</h3><p class="muted">Email: <a href="mailto:pareshp2006@gmail.com">pareshp2006@gmail.com</a></p><p class="muted">Phone: <a href="tel:8652237770">8652237770</a> / <a href="tel:9773237770">97732 37770</a></p><p class="muted">Address: Maharashtra, Mumbai, Ghatkopar, 400086</p><p class="muted"><a class="social-link" href="https://www.instagram.com/kalaai.by.paddy?cplk=MWxqMmljNjI2aHBkMQ==" target="_blank" rel="noopener noreferrer" aria-label="Follow Kalaai on Instagram"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 2h10a5 5 0 015 5v10a5 5 0 01-5 5H7a5 5 0 01-5-5V7a5 5 0 015-5zm0 2a3 3 0 00-3 3v10a3 3 0 003 3h10a3 3 0 003-3V7a3 3 0 00-3-3H7zm5 3.5A5.5 5.5 0 1116.5 13 5.5 5.5 0 0112 7.5zm0 2A3.5 3.5 0 1015.5 13 3.5 3.5 0 0012 9.5zm5.75-3.25a1.25 1.25 0 110 2.5 1.25 1.25 0 010-2.5z"/></svg>Instagram</a></p></div></div><div class="panel"><h2 class="serif">Send a Message</h2><form class="formgrid" data-form="contact"><div class="hp-field" aria-hidden="true"><label>Leave this field empty<input name="website" tabindex="-1" autocomplete="off"></label></div><label><span class="formlabel">Name *</span><input class="field" name="name" required></label><label><span class="formlabel">Email *</span><input class="field" name="email" type="email" required></label><label><span class="formlabel">Phone</span><input class="field" name="phone" type="tel"></label><label><span class="formlabel">Subject</span><input class="field" name="subject"></label><label class="wide"><span class="formlabel">Message *</span><textarea class="field" name="message" rows="5" required></textarea></label><label class="wide"><span class="formlabel">Reference Image</span><input class="field" name="referenceImage" type="file" accept="image/jpeg,image/png,image/webp,image/gif"></label><div class="wide"><button class="btn">Send Message</button><p class="notice" id="contactMsg"></p></div></form></div></div></section>`}
async function contactSubmit(e){e.preventDefault();const form=e.target,formData=new FormData(form);formData.set('type','contact');const msg=document.getElementById('contactMsg'),button=form.querySelector('button');button.disabled=true;const whatsappText=`Hello Kalaai,\n\nName: ${formData.get('name') || 'Not provided'}\nEmail: ${formData.get('email') || 'Not provided'}\nPhone: ${formData.get('phone') || 'Not provided'}\nSubject: ${formData.get('subject') || 'Not provided'}\n\nMessage:\n${formData.get('message') || 'No message supplied'}`;try{const r=await fetch('/api/enquiries',{method:'POST',body:formData});const d=await r.json();if(!r.ok)throw Error(d.message||'Unable to send');window.open(`https://wa.me/919773237770?text=${encodeURIComponent(whatsappText)}`,'_blank','noopener');msg.textContent='Your message and any reference image have been sent to Kalaai.';form.reset()}catch(err){msg.textContent=err.message}finally{button.disabled=false}}
async function subscribe(e){e.preventDefault();const form=e.target,msg=document.getElementById('subscribeMsg'),button=form.querySelector('button');button.disabled=true;msg.textContent='';try{const response=await fetch('/api/newsletter',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:form.querySelector('[name=email]').value,website:form.querySelector('[name=website]')?.value||''})});const result=await response.json();if(!response.ok)throw Error(result.message||'Unable to subscribe.');msg.textContent=result.message;form.reset()}catch(error){msg.textContent=error.message}finally{button.disabled=false}}
function navigate(page){state.page=page;state.quick=null;const hash=page==='product'?`#product/${state.selected||1}`:`#${page}`;history.replaceState(null,'',hash);render();window.scrollTo(0,0)}

function updateSeo(){const titles={home:'Kalaai — Bring Home Divinity',privacy:'Privacy Policy | Kalaai',terms:'Terms & Conditions | Kalaai',faq:'FAQs | Kalaai',shipping:'Shipping Information | Kalaai',returns:'Returns & Cancellations | Kalaai',shop:'Shop Handcrafted Creations | Kalaai',contact:'Contact Kalaai'};document.title=titles[state.page]||'Kalaai — Bring Home Divinity';let ogTitle=document.querySelector('meta[property="og:title"]');if(ogTitle)ogTitle.content=document.title;let desc=document.querySelector('meta[name="description"]');if(desc)desc.content=state.page==='privacy'?'Read how Kalaai collects, uses and protects information.':state.page==='terms'?'Terms and conditions for using the Kalaai website.':'Handcrafted resin art, spiritual decor and personalised gifts from Kalaai.';let ogDesc=document.querySelector('meta[property="og:description"]');if(ogDesc&&desc)ogDesc.content=desc.content;let robots=document.querySelector('meta[name="robots"]');if(robots)robots.content=['privacy','terms','home','shop','about','contact'].includes(state.page)?'index,follow':'noindex,nofollow';let canonical=document.querySelector('link[rel="canonical"]');if(!canonical){canonical=document.createElement('link');canonical.rel='canonical';document.head.append(canonical)}const canonicalPath=state.page==='privacy'?'/privacy-policy':state.page==='terms'?'/terms-and-conditions':'/';const canonicalBase=document.querySelector('meta[name="kalaai-site-url"]')?.content||'';if(canonicalBase){canonical.href=canonicalBase.replace(/\/$/,'')+canonicalPath;let og=document.querySelector('meta[property="og:url"]');if(!og){og=document.createElement('meta');og.setAttribute('property','og:url');document.head.append(og)}og.content=canonical.href;let image=document.querySelector('meta[property="og:image"]');if(image)image.content=canonicalBase.replace(/\/$/,'')+'/images/logo.png'}else canonical.remove()}
function getConsent(){try{return JSON.parse(localStorage.getItem('kalaai-cookie-consent')||'null')}catch(_){return null}}
function initCookieConsent(){if(!getConsent())showCookieBanner()}
function saveConsent(value){localStorage.setItem('kalaai-cookie-consent',JSON.stringify({...value,updatedAt:new Date().toISOString(),version:1}));document.getElementById('cookieConsent')?.remove();document.getElementById('cookieSettings')?.remove()}
function showCookieBanner(){if(document.getElementById('cookieConsent'))return;const el=document.createElement('section');el.id='cookieConsent';el.className='cookie-banner';el.setAttribute('aria-label','Cookie preferences');el.innerHTML='<div><strong>Your privacy matters</strong><p>We use essential browser storage for core features and remember your cookie choices. No optional analytics or marketing trackers are currently active. Read our <a href="/privacy-policy">Privacy Policy</a>.</p></div><div class="cookie-actions"><button type="button" class="btn" id="cookieAccept">Accept All</button><button type="button" class="btn outline" id="cookieReject">Reject Optional</button><button type="button" class="btn text-cookie" id="cookieManage">Manage Preferences</button></div>';document.body.append(el);el.querySelector('#cookieAccept').onclick=()=>saveConsent({essential:true,analytics:true,marketing:true});el.querySelector('#cookieReject').onclick=()=>saveConsent({essential:true,analytics:false,marketing:false});el.querySelector('#cookieManage').onclick=openCookieSettings}
function openCookieSettings(){document.getElementById('cookieConsent')?.remove();document.getElementById('cookieSettings')?.remove();const c=getConsent()||{};const el=document.createElement('div');el.id='cookieSettings';el.className='cookie-overlay';el.innerHTML=`<section class="cookie-dialog" role="dialog" aria-modal="true" aria-labelledby="cookieTitle"><h2 id="cookieTitle" class="serif">Cookie Preferences</h2><p>Essential storage is required for core website features. Optional analytics and marketing storage are currently not used by Kalaai.</p><label class="cookie-choice"><span><strong>Essential</strong><small>Cart, wishlist, security and preference storage</small></span><input type="checkbox" checked disabled aria-label="Essential storage always active"></label><label class="cookie-choice"><span><strong>Analytics</strong><small>Currently not configured</small></span><input id="consentAnalytics" type="checkbox" ${c.analytics?'checked':''}></label><label class="cookie-choice"><span><strong>Marketing</strong><small>Currently not configured</small></span><input id="consentMarketing" type="checkbox" ${c.marketing?'checked':''}></label><div class="cookie-actions"><button class="btn" id="saveCookiePrefs">Save Preferences</button><button class="btn outline" id="closeCookiePrefs">Cancel</button></div></section>`;document.body.append(el);el.querySelector('#saveCookiePrefs').onclick=()=>saveConsent({essential:true,analytics:el.querySelector('#consentAnalytics').checked,marketing:el.querySelector('#consentMarketing').checked});el.querySelector('#closeCookiePrefs').onclick=()=>el.remove()}
function initSequentialMotion(){
  const reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  document.body.classList.toggle('motion-ready',!reduce);
  const groups=[...document.querySelectorAll('main section, .benefits, .pagehero, .shoplayout, .detail, .panel, .footer')];
  groups.forEach(group=>{
    const children=[...group.querySelectorAll(':scope > .wrap > *, :scope > .wrap > .sectionhead, :scope > .wrap > .category-grid > *, :scope > .wrap > .productgrid > *, :scope > .wrap > .steps > *, :scope > .benefit-grid > *, :scope > .footgrid > *')];
    const direct=[...group.children].filter(el=>el.matches('.sectionhead,.category-grid,.productgrid,.promo,.editorial,.steps,.newsletter,.benefit-grid,.filters,.shopcontent,.panel,.detail > *'));
    const targets=[...new Set([...children,...direct])].filter(el=>!el.closest('.hero'));
    targets.forEach((el,i)=>{el.classList.add('reveal-item');el.style.setProperty('--reveal-delay',`${Math.min(i,7)*105}ms`)});
  });
  const all=[...document.querySelectorAll('.reveal-item')];
  if(reduce||!('IntersectionObserver' in window)){all.forEach(el=>el.classList.add('is-visible'));return}
  const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}})},{threshold:.12,rootMargin:'0px 0px -45px 0px'});
  all.forEach(el=>observer.observe(el));
}
function render(){let body=state.page==='privacy'?privacyPolicy():state.page==='terms'?termsPage():state.page==='faq'?faqPage():state.page==='shipping'?shippingPage():state.page==='returns'?returnsPage():state.page==='home'?home():state.page==='shop'?shop():state.page==='product'?detail():state.page==='cart'?cart():state.page==='wishlist'?wishlist():state.page==='custom'?custom():state.page==='about'?about():state.page==='contact'?contact():`<section class="wrap empty"><h2 class="serif">Page not found</h2><a class="btn" href="#home">Return Home</a></section>`;app.innerHTML=header()+body+footer();renderCounts();updateSeo();if(state.page==='shop'){if(state.cat.length)state.cat.forEach(c=>{let el=[...document.querySelectorAll('#filters input[type=checkbox]')].find(x=>x.parentElement.textContent.trim()===c);if(el)el.checked=true});applyShop()};initSequentialMotion()}
document.addEventListener('click',event=>{
  if(!(event.target instanceof Element))return;
  const action=event.target.closest('[data-action]');
  if(!action)return;
  const id=Number(action.dataset.id);
  switch(action.dataset.action){
    case'navigate':navigate(action.dataset.page);break;
    case'toggle-menu':document.getElementById('navlinks')?.classList.toggle('open');break;
    case'cookie-settings':openCookieSettings();break;
    case'shop-category':event.preventDefault();shopCategory(action.dataset.category);break;
    case'toggle-wish':toggleWish(id);break;
    case'quick-view':quickView(id);break;
    case'open-product':openProduct(id);break;
    case'add-cart':addCart(id);break;
    case'add-cart-state':addCart(id,state.qty,personalDetails());break;
    case'close-filters':state.filterOpen=false;render();break;
    case'apply-shop':applyShop();break;
    case'clear-filters':clearFilters();break;
    case'toggle-filters':state.filterOpen=!state.filterOpen;render();break;
    case'set-price':window.minPrice=Number(action.dataset.min);window.maxPrice=Number(action.dataset.max);render();break;
    case'clear-search':state.query='';render();break;
    case'lightbox':lightbox(action.dataset.src);break;
    case'detail-image':{const image=document.getElementById('detailImage');if(image)image.src=action.dataset.src;break}
    case'detail-qty':state.qty=Math.max(1,state.qty+Number(action.dataset.change));document.getElementById('qnum').textContent=state.qty;break;
    case'set-tab':state.tab=action.dataset.tab;render();break;
    case'modal-backdrop':if(action.matches('.modalback')&&(action.querySelector(':scope > img')||event.target===action))action.remove();break;
    case'close-modal':action.closest('.modalback')?.remove();break;
    case'quick-view-qty':window.qvqty=Math.max(1,(window.qvqty||1)+Number(action.dataset.change));document.getElementById('qvnum').textContent=window.qvqty;break;
    case'quick-view-add':addCart(id,window.qvqty||1);action.closest('.modalback')?.remove();break;
    case'modal-open-product':event.preventDefault();action.closest('.modalback')?.remove();openProduct(id);break;
    case'cart-qty':cartQty(id,Number(action.dataset.change));break;
    case'remove-cart':removeCart(id);break;
    case'checkout':checkoutDemo();break;
    case'wishlist-move-cart':addCart(id);toggleWish(id);break;
  }
});
document.addEventListener('input',event=>{
  const input=event.target;
  if(!(input instanceof HTMLInputElement))return;
  if(input.dataset.input==='search'){state.query=input.value;applyShop()}
  if(input.dataset.input==='price-range'){window.maxPrice=Number(input.value);document.getElementById('rangeValue').textContent=money(input.value);applyShop()}
});
document.addEventListener('change',event=>{
  const input=event.target;
  if(!(input instanceof HTMLInputElement||input instanceof HTMLSelectElement))return;
  if(input.dataset.categoryFilter){toggleCat(input.dataset.categoryFilter);return}
  if(input.dataset.change==='sort'){state.sort=input.value;applyShop();return}
  if(input.dataset.change==='preview-file'){previewFile(input);return}
  if(input.dataset.change==='preview-enquiry'){previewEnquiry(input);return}
  if(input.dataset.change==='apply-shop')applyShop();
});
document.addEventListener('submit',event=>{
  const form=event.target;
  if(!(form instanceof HTMLFormElement))return;
  switch(form.dataset.form){
    case'newsletter':subscribe(event);break;
    case'custom-enquiry':submitEnquiry(event);break;
    case'contact':contactSubmit(event);break;
  }
});
function routeFromHash(hash){const [page,query='']=hash.split('?');if(page==='shop'){if(query){const category=new URLSearchParams(query).get('cat');state.cat=categories.includes(category)?[category]:[]}state.page='shop';return}if(page.startsWith('product/')){state.selected=+page.split('/')[1];state.page='product';return}state.page=['home','cart','wishlist','custom','about','contact','privacy','terms','faq','shipping','returns'].includes(page)?page:'home'}
window.addEventListener('hashchange',()=>{routeFromHash(location.hash.slice(1));render()});
window.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.modalback')?.remove()});
// expose interaction handlers for the static browser app
Object.assign(window,{openCookieSettings,navigate,toggleWish,addCart,quickView,openProduct,cartQty,removeCart,checkoutDemo,shopCategory,toggleCat,applyShop,clearFilters,personalDetails,previewFile,lightbox,subscribe,submitEnquiry,previewEnquiry,contactSubmit,render,state,money});
async function bootstrap(){try{const r=await fetch('/api/products');if(r.ok){const remote=await r.json();if(remote.length)products=remote}}catch(e){console.warn('API unavailable; using bundled catalogue',e)}try{const response=await fetch('/api/checkout/config');if(!response.ok)throw Error(`Checkout configuration returned ${response.status}`);checkoutConfig=await response.json()}catch(error){console.error('Checkout configuration unavailable:',error)}if(location.hash)routeFromHash(location.hash.slice(1));else if(location.pathname==='/privacy-policy')state.page='privacy';else if(location.pathname==='/terms-and-conditions')state.page='terms';else if(location.pathname==='/faq')state.page='faq';else if(location.pathname==='/shipping')state.page='shipping';else if(location.pathname==='/returns')state.page='returns';else state.page='home';render();initCookieConsent();updateSeo()}bootstrap();
